    [Test, Retry(3)] // timing-sensitive
    public async Task TestCompositeRemainingTimeDistribution()
    {
        var mockProvider = new Mock<IDistributedLockProvider>();
        var mockLockA = new Mock<IDistributedLock>();
        var mockLockB = new Mock<IDistributedLock>();
        var mockHandleA = new Mock<IDistributedSynchronizationHandle>();
        var mockHandleB = new Mock<IDistributedSynchronizationHandle>();

        mockProvider.Setup(p => p.CreateLock("A")).Returns(mockLockA.Object);
        mockProvider.Setup(p => p.CreateLock("B")).Returns(mockLockB.Object);

        List<TimeSpan> capturedTimeouts = [];

        mockLockA.Setup(l => l.TryAcquireAsync(It.IsAny<TimeSpan>(), default))
            .Returns(async (TimeSpan timeout, CancellationToken _) =>
            {
                capturedTimeouts.Add(timeout);
                await Task.Delay(TimeSpan.FromMilliseconds(100));
                return mockHandleA.Object;
            });

        mockLockB.Setup(l => l.TryAcquireAsync(It.IsAny<TimeSpan>(), default))
            .ReturnsAsync((TimeSpan timeout, CancellationToken _) =>
            {
                capturedTimeouts.Add(timeout);
                return mockHandleB.Object;
            });

        var names = new List<string> { "A", "B" };
        var totalTimeout = TimeSpan.FromSeconds(5);

        await using var result = await mockProvider.Object.TryAcquireAllLocksAsync(names, totalTimeout, default);

        Assert.That(result, Is.Not.Null);
        Assert.That(capturedTimeouts.Count, Is.EqualTo(2));

        Assert.That(capturedTimeouts[0].TotalMilliseconds, Is.EqualTo(totalTimeout.TotalMilliseconds).Within(TestHelper.IsCi ? 50 : 2));

        Assert.That(capturedTimeouts[1], Is.LessThan(totalTimeout));
        Assert.That(capturedTimeouts[1], Is.GreaterThanOrEqualTo(TimeSpan.Zero));
    }

    [Test]
    public async Task TestCompositeHandleLostToken()
    {
        var mockProvider = new Mock<IDistributedLockProvider>();
        var mockLockA = new Mock<IDistributedLock>();
        var mockLockB = new Mock<IDistributedLock>();

        var ctsA = new CancellationTokenSource();
        var ctsB = new CancellationTokenSource();

        var mockHandleA = new Mock<IDistributedSynchronizationHandle>();
        var mockHandleB = new Mock<IDistributedSynchronizationHandle>();

        mockHandleA.Setup(h => h.HandleLostToken).Returns(ctsA.Token);
        mockHandleB.Setup(h => h.HandleLostToken).Returns(ctsB.Token);

        mockProvider.Setup(p => p.CreateLock("A")).Returns(mockLockA.Object);
        mockProvider.Setup(p => p.CreateLock("B")).Returns(mockLockB.Object);

        mockLockA.Setup(l => l.TryAcquireAsync(It.IsAny<TimeSpan>(), default))
            .ReturnsAsync(mockHandleA.Object);
        mockLockB.Setup(l => l.TryAcquireAsync(It.IsAny<TimeSpan>(), default))
            .ReturnsAsync(mockHandleB.Object);

        var names = new List<string> { "A", "B" };
        var result = await mockProvider.Object.TryAcquireAllLocksAsync(names, TimeSpan.FromSeconds(10), default);

        Assert.That(result, Is.Not.Null);
        Assert.That(result!.HandleLostToken.CanBeCanceled, Is.True);

        ctsA.Cancel();

        Assert.That(result.HandleLostToken.IsCancellationRequested, Is.True);

        await result.DisposeAsync();
        ctsA.Dispose();
        ctsB.Dispose();
    }

    [Test, Combinatorial]
    public async Task TestCompositeObserveLockLostTokenPassesLinkedTokenToSubsequentAcquires([Values] bool observe, [Values] bool isAsync)
    {
        using var ctsA = new CancellationTokenSource();
        var handleA = CreateHandle(ctsA.Token);
        var handleB = CreateHandle(CancellationToken.None);
        bool? tokenBCanceledByLoss = null;
        var provider = CreateProvider(
            isAsync,
            ("A", (_, _) => handleA.Object),
            ("B", (_, c) =>
            {
                ctsA.Cancel();
                tokenBCanceledByLoss = c.IsCancellationRequested;
                return handleB.Object;
            }));

        await using var result = await AcquireAllAsync(provider, ["A", "B"], isTry: true, isAsync, observe, default);

        Assert.That(tokenBCanceledByLoss, Is.EqualTo(observe));
        Assert.That(result, observe ? Is.Null : Is.Not.Null);
    }

    [Test, Combinatorial]
    public async Task TestCompositeLockLostDuringAcquisition([Values] bool isTry, [Values] bool isAsync)
    {
        using var ctsA = new CancellationTokenSource();
        var handleA = CreateHandle(ctsA.Token);
        var provider = CreateProvider(
            isAsync,
            ("A", (_, _) => handleA.Object),
            ("B", (_, c) =>
            {
                ctsA.Cancel();
                c.ThrowIfCancellationRequested();
                throw new AssertionException("should have been canceled");
            }));

        await AssertLostAsync(provider, ["A", "B"], isTry, isAsync);
        VerifyDisposedOnce(handleA, isAsync);
    }

    [Test, Combinatorial]
    public async Task TestCompositeLockLostAfterLastAcquireReleasesHandles([Values] bool isTry, [Values] bool isAsync)
    {
        using var ctsA = new CancellationTokenSource();
        var handleA = CreateHandle(ctsA.Token);
        var handleB = CreateHandle(CancellationToken.None);
        var provider = CreateProvider(
            isAsync,
            ("A", (_, _) => handleA.Object),
            ("B", (_, _) => { ctsA.Cancel(); return handleB.Object; }));

        await AssertLostAsync(provider, ["A", "B"], isTry, isAsync);
        VerifyDisposedOnce(handleA, isAsync);
        VerifyDisposedOnce(handleB, isAsync);
    }

    [Test, Combinatorial]
    public void TestCompositeCallerCancellationStillThrowsOperationCanceled([Values] bool isTry, [Values] bool isAsync)
    {
        using var callerCts = new CancellationTokenSource();
        var handleA = CreateHandle(CancellationToken.None);
        var provider = CreateProvider(
            isAsync,
            ("A", (_, _) => handleA.Object),
            ("B", (_, c) =>
            {
                callerCts.Cancel();
                c.ThrowIfCancellationRequested();
                throw new AssertionException("should have been canceled");
            }));

        var ex = Assert.CatchAsync<OperationCanceledException>(
            () => AcquireAllAsync(provider, ["A", "B"], isTry, isAsync, observeLockLostToken: true, callerCts.Token).AsTask());
        Assert.That(ex!.CancellationToken.IsCancellationRequested, Is.True);
        VerifyDisposedOnce(handleA, isAsync);
    }

    [Test, Combinatorial]
    public async Task TestCompositeLockLostWhenAlreadyCancelledHandleToken([Values] bool isTry, [Values] bool isAsync)
    {
        var handleA = CreateHandle(new CancellationToken(canceled: true));
        var bInvoked = false;
        var provider = CreateProvider(
            isAsync,
            ("A", (_, _) => handleA.Object),
            ("B", (_, _) => { bInvoked = true; return CreateHandle(CancellationToken.None).Object; }));

        await AssertLostAsync(provider, ["A", "B"], isTry, isAsync);
        Assert.That(bInvoked, Is.False);
        VerifyDisposedOnce(handleA, isAsync);
    }

